// 递归树逐层记账（伪代码思路，实际是数学推导）
// 层 k: 节点数 = 2^k, 每个规模 = n/2^k, 每个工作量 = c*n/2^k
// 层总工作量 = 2^k * c*n/2^k = c*n   —— 每层恒定
// 层数 = log2(n), 总计 = c*n*log2(n) = O(n log n)

// 主定理对照（JS 表达归并排序骨架，验证递归式来源）
function mergeSort(a) {
  if (a.length <= 1) return a;                 // O(1) 基准情形
  const mid = a.length >> 1;
  const left = mergeSort(a.slice(0, mid));     // T(n/2)
  const right = mergeSort(a.slice(mid));       // T(n/2)
  return merge(left, right);                   // O(n) 线性合并 => f(n)
}
// T(n) = 2T(n/2) + O(n)  =>  O(n log n)

function merge(l, r) {
  const out = [];
  while (l.length && r.length)
    out.push(l[0] <= r[0] ? l.shift() : r.shift());
  return out.concat(l, r);
}
